var RAMP=' .:-=+*#%@';
function toAscii(w, h, getPx, cols, invert){
  cols=cols>0?cols:80; invert=!!invert;
  if(!(w>0)||!(h>0)) return null;
  var rows=Math.max(1,Math.round(h*cols/w/2));
  var out=[];
  for(var y=0;y<rows;y++){
    var line='';
    for(var x=0;x<cols;x++){
      var sx=Math.min(w-1,Math.floor(x/w*cols* (w/cols)));
      var sy=Math.min(h-1,Math.floor(y/rows*h));
      var p=getPx(sx,sy); // {r,g,b}
      var lum=(p.r*0.299+p.g*0.587+p.b*0.114)/255;
      if(invert) lum=1-lum;
      var idx=Math.min(RAMP.length-1,Math.floor(lum*RAMP.length));
      line+=RAMP[idx];
    }
    out.push(line);
  }
  return out.join('\n');
}
var EXPORTS={toAscii:toAscii,RAMP:RAMP};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ImgToAsciiForgePure = EXPORTS; }
